import { unstable_cache, revalidateTag } from 'next/cache'

export interface Product {
  id: string
  name: string
  price: number
  inventory: number
  available: boolean
  sku: string
}

async function fetchProductsFromERP(): Promise<Product[]> {
  return [
    { id: '1', name: 'Wireless Headphones', price: 199.99, inventory: 150, available: true, sku: 'WH-001' },
    { id: '2', name: 'Mechanical Keyboard', price: 149.99, inventory: 80, available: true, sku: 'MK-002' },
    { id: '3', name: 'USB-C Hub', price: 79.99, inventory: 0, available: false, sku: 'UH-003' },
    { id: '4', name: 'Webcam 4K', price: 249.99, inventory: 45, available: true, sku: 'WC-004' },
  ]
}

export const getProducts = unstable_cache(
  fetchProductsFromERP,
  ['products-list'],
  { tags: ['products'] }
)

